import{_ as t,o as n,c as a,ah as o}from"./chunks/framework.BsNNkeaH.js";const b=JSON.parse('{"title":"Boarding","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/internat/index.md","filePath":"src/en/guide/internat/index.md"}'),r={name:"en/guide/internat/index.md"};function i(s,e,d,g,h,l){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="boarding" tabindex="-1">Boarding <a class="header-anchor" href="#boarding" aria-label="Permalink to &quot;Boarding&quot;">​</a></h1><p>As the boarding manager, you have two responsibilities in ERA: managing beds (creating and editing them, and assigning a boarding student to each) and recording boarding attendance every day, both in the evening and in the morning. The left-hand menu gives you access to two pages, in the &quot;Student services&quot; group: <strong>Boarding beds</strong> and <strong>Boarding attendance</strong>.</p><h2 id="managing-beds" tabindex="-1">Managing beds <a class="header-anchor" href="#managing-beds" aria-label="Permalink to &quot;Managing beds&quot;">​</a></h2><p>The <strong>Boarding beds</strong> page lists every bed in the boarding house, with its site, room, bed, and the student occupying it (or &quot;Unassigned&quot; if it&#39;s free). You can filter the list by site using the dropdown at the top of the page, or search for a bed by room or bed code. Click a row to open a summary panel showing the site and the occupant.</p><h3 id="creating-a-bed" tabindex="-1">Creating a bed <a class="header-anchor" href="#creating-a-bed" aria-label="Permalink to &quot;Creating a bed&quot;">​</a></h3><ol><li>Click <strong>New bed</strong> at the top of the <strong>Boarding beds</strong> page.</li><li>Choose the <strong>Site</strong> this bed belongs to.</li><li>Fill in the <strong>Room</strong> (the room code) and the <strong>Bed</strong> (the bed code within that room).</li><li>If a boarding student should occupy this bed as soon as it&#39;s created, select them in the <strong>Occupant</strong> field. You can leave this field empty and assign a student later.</li><li>Click <strong>Save</strong>.</li></ol><p>Only students who don&#39;t already have a bed appear in the <strong>Occupant</strong> list (plus, on the edit page, the student already assigned to that bed).</p><h3 id="editing-a-bed-or-reassigning-its-occupant" tabindex="-1">Editing a bed or reassigning its occupant <a class="header-anchor" href="#editing-a-bed-or-reassigning-its-occupant" aria-label="Permalink to &quot;Editing a bed or reassigning its occupant&quot;">​</a></h3><ol><li>From the <strong>Boarding beds</strong> page, click <strong>Edit</strong> on the row for the bed in question.</li><li>Update the site, room, bed, or occupant as needed. To free up a bed, choose <strong>Unassigned</strong> again in the <strong>Occupant</strong> field; to assign a different student, select them from the list.</li><li>Click <strong>Save changes</strong>.</li></ol><h3 id="deleting-a-bed" tabindex="-1">Deleting a bed <a class="header-anchor" href="#deleting-a-bed" aria-label="Permalink to &quot;Deleting a bed&quot;">​</a></h3><p>From the <strong>Boarding beds</strong> page, click <strong>Delete</strong> on the row for the bed in question, then confirm in the dialog that appears. An occupied bed cannot be deleted: first free its occupant (by editing the bed and setting <strong>Occupant</strong> back to &quot;Unassigned&quot;) before deleting it.</p><h2 id="recording-boarding-attendance" tabindex="-1">Recording boarding attendance <a class="header-anchor" href="#recording-boarding-attendance" aria-label="Permalink to &quot;Recording boarding attendance&quot;">​</a></h2><p>The <strong>Boarding attendance</strong> page lets you record, for every student who already has a bed assigned, whether they are present or absent — in the evening or in the morning. Only students who already have a bed assigned (see &quot;Managing beds&quot; above) appear in this list; if the list is empty, no bed has been assigned yet.</p><ol><li>Open the <strong>Boarding attendance</strong> page.</li><li>Choose the relevant <strong>date</strong> with the date picker at the top of the page.</li><li>Choose the <strong>period</strong>: <strong>Evening</strong> or <strong>Morning</strong>. Changing the date or the period automatically reloads the list with any attendance already recorded for that choice.</li><li>For each student in the list (shown with their site, room, and bed), tap <strong>Present</strong> or <strong>Absent</strong>.</li><li>Once every row has been checked, click <strong>Save</strong>.</li></ol><div class="tip custom-block"><p class="custom-block-title">A roll call built for phones</p><p>Each student has a <strong>Present</strong> / <strong>Absent</strong> switch; everyone starts as <strong>Present</strong>, and the <strong>Everyone present</strong> button resets the whole list to that status. The counters above the list update on every tap, and the bottom bar shows &quot;Unsaved changes&quot; until you click <strong>Save</strong> — leaving the page or changing the date at that point asks for confirmation. Attendance can&#39;t be recorded for a future date.</p></div><p>You can go back to a date you&#39;ve already recorded at any time to correct a status: the values already saved for that date and period are pre-filled.</p>',16)])])}const u=t(r,[["render",i]]);export{b as __pageData,u as default};
